-- Configuration centre: what Jaska has to set up, in priority order. Secrets never go here:
-- the "where_to" column says which environment variable or screen receives each value.

insert into config_items (key, priority, area, title, why, steps, minutes, where_to, test, agents, external_wait) values
('empresa', 1, 'Empresa y legal', 'Forma jurídica, gestoría y alta de IVA',
 'TikTok Shop en España exige empresa registrada con NIF/IVA; Stripe y Meta piden datos de empresa para cobrar y verificar.',
 array['Elige con la gestoría autónomo o SL (SL si sois varios socios).', 'Pide el alta censal (modelo 036/037) y el NIF; valora el alta en OSS si venderéis fuera de España.', 'Abre una cuenta bancaria solo para el negocio.', 'Apunta razón social, NIF y dirección en Ajustes cuando estén.'],
 '1-4 semanas (gestión externa)', 'Gestoría; luego Ajustes del panel', 'Tienes NIF y certificado de alta', array['finanzas', 'cumplimiento'], true),
('legal_textos', 2, 'Empresa y legal', 'Textos legales y aviso de cookies',
 'Obligatorios antes de abrir la tienda al público (RGPD, LSSI, consumo).',
 array['Pide a la gestoría o a un abogado: aviso legal, condiciones de venta, privacidad, cookies y envíos/devoluciones.', 'Envíamelos y los pongo en las páginas legales.', 'Decidid si las visitas anónimas necesitan consentimiento de cookies.'],
 '1-2 semanas', 'Me los pasas como documento', 'Las 5 páginas legales muestran el texto definitivo', array['cumplimiento'], true),
('meta_business', 3, 'Meta / Instagram', 'Meta Business Manager y verificación de empresa',
 'Necesario para publicar en Instagram por API con acceso avanzado y para anuncios en Meta.',
 array['Crea el portfolio en business.facebook.com con el correo de la marca.', 'Añade la página de Facebook y la cuenta de Instagram profesional.', 'Inicia "Verificación de la empresa" (necesita los datos de la empresa del punto 1).', 'Crea una app en developers.facebook.com tipo "Empresa" y solicita instagram_business_content_publish (revisión de la app).'],
 '30 min + días o semanas de revisión', 'Credenciales en .env.local (te diré los nombres al conectar)', 'La app aparece como verificada y con el permiso aprobado', array['publicacion', 'anuncios'], true),
('tiktok_dev', 4, 'TikTok', 'App de TikTok for Developers y auditoría de Content Posting API',
 'Sin la auditoría, lo publicado por API solo puede ser privado (máx. 5 usuarios en 24 h, a verificar). Mientras, se puede enviar como borrador a la bandeja de la app.',
 array['Crea una cuenta en developers.tiktok.com con el correo de la marca.', 'Crea una app, añade "Login Kit" y "Content Posting API" y solicita video.publish.', 'Rellena la revisión de la app (vídeo de demostración) y después la auditoría de Direct Post.', 'Avísame cuando tengas Client Key y Client Secret (no los pegues en el chat).'],
 '1 h + semanas de revisión (a verificar)', '.env.local: TIKTOK_CLIENT_KEY, TIKTOK_CLIENT_SECRET', 'Una publicación de prueba llega como borrador a tu bandeja de TikTok', array['publicacion'], true),
('anthropic', 5, 'IA', 'Cuenta y clave de la API de Anthropic + límite de gasto',
 'Los agentes razonan con Claude. Sin clave funcionan en modo simulado con respuestas de prueba.',
